import {
  CANONICAL_MODEL_CAPABILITY_ID_PATTERN,
  capabilityRegistrationSchema,
  connectorCatalogSchema,
  connectorRegistrationSchema,
  connectorStatusSchema,
  stableDigest,
  type CapabilityRegistration,
  type ConnectorCatalog,
  type ConnectorRegistration,
  type ConnectorStatus,
} from "@ehf/contracts";

/**
 * The connector registry: every gateway adapter binding that can serve a canonical capability.
 *
 * `config/connector-catalog.json` (generated by scripts/sync-connector-catalog.mjs) is the
 * seed. Seeding is additive and never lowers an operator decision: a connector an operator
 * quarantined or retired stays that way, and one an operator promoted to `live_ready` is not
 * demoted by a re-seed. An upstream quarantine always applies.
 */
export type ConnectorClient = {
  query<T = Record<string, unknown>>(text: string, values?: unknown[]): Promise<{ rows: T[]; rowCount?: number | null }>;
};

export type ConnectorRecord = {
  connector: ConnectorRegistration;
  digest: string;
  createdAt: string;
  updatedAt: string;
};

type ConnectorRow = { definition: unknown; definition_digest: string; status: ConnectorStatus; created_at: Date; updated_at: Date };

function mapConnector(row: ConnectorRow): ConnectorRecord {
  const connector = connectorRegistrationSchema.parse({ ...(row.definition as Record<string, unknown>), status: row.status });
  return { connector, digest: stableDigest(connector), createdAt: row.created_at.toISOString(), updatedAt: row.updated_at.toISOString() };
}

const CATALOG_OWNER = "platform.catalog";
const CANONICAL_JURISDICTION_PATTERN = /^([a-z]{2}(_[a-z0-9]+)?|global|unresolved)$/;

/** A registry-valid draft contract for a catalog capability that has none yet. */
export function catalogCapabilityDraft(capability: ConnectorCatalog["capabilities"][number], defaultTimeoutMs = 15_000): CapabilityRegistration {
  return capabilityRegistrationSchema.parse({
    id: capability.capabilityId,
    kind: capability.kind,
    effect: capability.effect,
    adapterBindingId: capability.defaultConnectorId ?? `unconfigured:${capability.capabilityId.replace(/\.v[0-9]+$/, "").replaceAll(/[._]/g, "-")}`,
    inputSchema: { type: "object" },
    outputSchema: { type: "object" },
    timeoutMs: capability.kind === "model" ? 45_000 : defaultTimeoutMs,
    maxAttempts: 1,
    idempotent: capability.effect === "read" || capability.effect === "none",
    description: capability.description,
    owner: CATALOG_OWNER,
    dataClasses: capability.dataClasses,
    status: "draft",
  });
}

export async function seedConnectorCatalog(db: ConnectorClient, input: unknown): Promise<{
  connectorsCreated: number;
  connectorsUpdated: number;
  capabilitiesCreated: number;
}> {
  const catalog = connectorCatalogSchema.parse(input);
  const connectors = catalog.connectors.map((connector) => ({ id: connector.connectorId, definition: connector, digest: stableDigest(connector) }));
  const upsert = await db.query<{ inserted: boolean }>(`
    with incoming as (
      select item->>'id' connector_id, item->'definition' definition, item->>'digest' definition_digest
      from jsonb_array_elements($1::jsonb) item
    )
    insert into harness_gateway.connector_registry
      (connector_id, capability_id, adapter_id, provider_id, definition, definition_digest, status)
    select connector_id, definition->>'capabilityId', definition->>'adapterId', definition->>'providerId',
      definition, definition_digest, definition->>'status'
    from incoming
    on conflict (connector_id) do update set
      capability_id = excluded.capability_id,
      adapter_id = excluded.adapter_id,
      provider_id = excluded.provider_id,
      definition = excluded.definition,
      definition_digest = excluded.definition_digest,
      status = case
        when connector_registry.status in ('quarantined', 'retired') then connector_registry.status
        when excluded.status = 'quarantined' then 'quarantined'
        when connector_registry.status = 'live_ready' then 'live_ready'
        else excluded.status
      end,
      updated_at = now()
    where connector_registry.definition_digest is distinct from excluded.definition_digest
      or (excluded.status = 'quarantined' and connector_registry.status not in ('quarantined', 'retired'))
    returning (xmax = 0) inserted
  `, [JSON.stringify(connectors)]);
  const connectorsCreated = upsert.rows.filter((row) => row.inserted).length;

  const drafts = catalog.capabilities.map((capability) => {
    const definition = catalogCapabilityDraft(capability);
    return { id: definition.id, definition, digest: stableDigest(definition), owner: definition.owner };
  });
  const seeded = await db.query(`
    insert into harness_gateway.capability_registry (capability_id, definition, definition_digest, status, owner)
    select item->>'id', item->'definition', item->>'digest', 'draft', item->>'owner'
    from jsonb_array_elements($1::jsonb) item
    on conflict (capability_id) do nothing
  `, [JSON.stringify(drafts)]);
  return {
    connectorsCreated,
    connectorsUpdated: upsert.rows.length - connectorsCreated,
    capabilitiesCreated: seeded.rowCount ?? 0,
  };
}

export type ConnectorFilter = {
  capabilityId?: string;
  adapterId?: string;
  providerId?: string;
  status?: ConnectorStatus;
  /** v2 canonical model: connectors whose canonical scope includes this jurisdiction token. */
  jurisdiction?: string;
  /** v2 canonical model: connectors serving this `<path>.intelligence.<jurisdiction>` key. */
  canonicalCapabilityId?: string;
  /**
   * Only connectors a release may bind: not quarantined or retired, and not a v2 correction or
   * quarantine. Platform connectors without a canonical mapping are bindable.
   */
  bindable?: boolean;
  limit?: number;
  cursor?: string;
};

function decodeConnectorCursor(cursor: string | undefined): string | null {
  if (!cursor) return null;
  try {
    const value = JSON.parse(Buffer.from(cursor, "base64url").toString("utf8")) as { id?: unknown };
    if (typeof value?.id !== "string" || !value.id) throw new Error("pagination.cursor_invalid");
    return value.id;
  } catch {
    throw new Error("pagination.cursor_invalid");
  }
}

export async function listConnectors(db: ConnectorClient, filter: ConnectorFilter = {}): Promise<{ items: ConnectorRecord[]; nextCursor: string | null }> {
  const limit = filter.limit ?? 100;
  if (!Number.isInteger(limit) || limit < 1 || limit > 500) throw new Error("pagination.limit_invalid");
  const status = filter.status === undefined ? null : connectorStatusSchema.parse(filter.status);
  const after = decodeConnectorCursor(filter.cursor);
  if (filter.jurisdiction !== undefined && !CANONICAL_JURISDICTION_PATTERN.test(filter.jurisdiction)) throw new Error("connector.jurisdiction_invalid");
  if (filter.canonicalCapabilityId !== undefined && !CANONICAL_MODEL_CAPABILITY_ID_PATTERN.test(filter.canonicalCapabilityId)) {
    throw new Error("connector.canonical_capability_invalid");
  }
  const result = await db.query<ConnectorRow & { connector_id: string }>(`
    select connector_id, definition, definition_digest, status, created_at, updated_at
    from harness_gateway.connector_registry
    where ($1::text is null or capability_id = $1)
      and ($2::text is null or adapter_id = $2)
      and ($3::text is null or provider_id = $3)
      and ($4::text is null or status = $4)
      and ($5::text is null or connector_id > $5)
      and ($7::text is null or coalesce(definition->'canonical'->'jurisdictions', '[]'::jsonb) ? $7)
      and ($8::text is null or coalesce(definition->'canonical'->'capabilityIds', '[]'::jsonb) ? $8)
      and (not $9::boolean or (status not in ('quarantined', 'retired')
        and coalesce(definition->'canonical'->>'runtimeDisposition', 'alias_pending_approval') = 'alias_pending_approval'))
    order by connector_id
    limit $6
  `, [filter.capabilityId ?? null, filter.adapterId ?? null, filter.providerId ?? null, status, after, limit + 1,
    filter.jurisdiction ?? null, filter.canonicalCapabilityId ?? null, filter.bindable === true]);
  const rows = result.rows.slice(0, limit);
  const last = rows.at(-1);
  return {
    items: rows.map(mapConnector),
    nextCursor: result.rows.length > limit && last ? Buffer.from(JSON.stringify({ id: last.connector_id })).toString("base64url") : null,
  };
}

/**
 * Register or update one connector outside the catalog seed: a concrete connector an operator
 * created from a connector template (gateway POST /v1/connectors). Like the seed, it never
 * lifts a connector an operator quarantined or retired.
 */
export async function upsertConnector(db: ConnectorClient, input: unknown): Promise<{ record: ConnectorRecord; created: boolean }> {
  const connector = connectorRegistrationSchema.parse(input);
  const digest = stableDigest(connector);
  const result = await db.query<ConnectorRow & { inserted: boolean }>(`
    insert into harness_gateway.connector_registry
      (connector_id, capability_id, adapter_id, provider_id, definition, definition_digest, status)
    values ($1, $2, $3, $4, $5::jsonb, $6, $7)
    on conflict (connector_id) do update set
      capability_id = excluded.capability_id,
      adapter_id = excluded.adapter_id,
      provider_id = excluded.provider_id,
      definition = excluded.definition,
      definition_digest = excluded.definition_digest,
      status = case
        when connector_registry.status in ('quarantined', 'retired') then connector_registry.status
        else excluded.status
      end,
      updated_at = now()
    returning definition, definition_digest, status, created_at, updated_at, (xmax = 0) inserted
  `, [connector.connectorId, connector.capabilityId, connector.adapterId, connector.providerId, JSON.stringify(connector), digest, connector.status]);
  const row = result.rows[0];
  if (!row) throw new Error("connector.upsert_failed");
  return { record: mapConnector(row), created: row.inserted };
}

export async function getConnector(db: ConnectorClient, connectorId: string): Promise<ConnectorRecord | null> {
  const result = await db.query<ConnectorRow>(`
    select definition, definition_digest, status, created_at, updated_at
    from harness_gateway.connector_registry where connector_id = $1
  `, [connectorId]);
  const row = result.rows[0];
  return row ? mapConnector(row) : null;
}
